"""Perfil de usuario (Mi perfil)

Ejecutar desde la raíz del proyecto:   python instalar_perfil_usuario.py
Idempotente, sin .bak. Cada archivo debe estar en alguna de las versiones conocidas (la actual de Cristian, o la de
una etapa intermedia del trabajo de Emilio); si alguno tiene cambios distintos, NO se instala nada y se indica cuál.
"""
import base64, hashlib, io, json, os, sys, zipfile

# Hashes de los estados de partida aceptados por archivo (None = el archivo no existía) y archivos que se eliminan.
ACEPTADAS = json.loads("{\"aplicacion_principal/vistas.py\": [\"8d7b19c79d0edeee70775fee450981b27a607441b92d1ebdb5a9ad522d4b07e0\"], \"componentes_plataforma/acceso/pantalla.py\": [\"fff9165b4f5670cbd6d15f43025f38ae0c9f64e2172add831ab858b873a73f0d\"], \"componentes_plataforma/barra_superior/barra.py\": [\"26171c57f6954422ca6710e5bdbd974d6a6b3f5f372f03c4a3a535f89b945470\", \"eade0cf7399b1428991e31392bdfae77aa12d54b4e361390787545dba7b80855\"], \"componentes_plataforma/barra_superior/usuario_menu.html\": [\"c78720460b4a10a38fd3eae91ded318f74adfd79f76af351e42677c2474c4e09\"], \"componentes_plataforma/perfil/__init__.py\": [null], \"componentes_plataforma/perfil/almacen.py\": [null], \"componentes_plataforma/perfil/datos.json\": [null], \"componentes_plataforma/perfil/datos.py\": [null], \"componentes_plataforma/perfil/esquema.sql\": [null], \"componentes_plataforma/perfil/estilos.css\": [null], \"componentes_plataforma/perfil/estilos.py\": [null], \"componentes_plataforma/perfil/panel.py\": [null], \"componentes_plataforma/perfil/secciones.py\": [null], \"componentes_plataforma/perfil/validacion.py\": [null], \"herramientas/gestor_autenticacion.py\": [\"e7eac40ed051eeefa03bc813f3e2930f2ea5367e9f3e232842b1e593571669a6\"]}")
ARCHIVOS = ["aplicacion_principal/vistas.py", "componentes_plataforma/acceso/pantalla.py", "componentes_plataforma/barra_superior/barra.py", "componentes_plataforma/barra_superior/usuario_menu.html", "componentes_plataforma/perfil/__init__.py", "componentes_plataforma/perfil/almacen.py", "componentes_plataforma/perfil/datos.json", "componentes_plataforma/perfil/datos.py", "componentes_plataforma/perfil/esquema.sql", "componentes_plataforma/perfil/estilos.css", "componentes_plataforma/perfil/estilos.py", "componentes_plataforma/perfil/panel.py", "componentes_plataforma/perfil/secciones.py", "componentes_plataforma/perfil/validacion.py", "herramientas/gestor_autenticacion.py"]
BORRAR = []
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
